:root {
  --cream: #f5efe2;
  --ink-dark: #2c2318;
  --rust: #b5451b;
  --slate-blue: #4a6580;
  --dusty-rose: #c97b84;
  --gold: #c89a2e;
  --muted: #7a6e63;
  --border: #d4c5a9;
  --green-status: #3a7d54;
  --green-status-bg: #d4edde;
  --paper: #fdf8f0;
}

article.ticket {
  background-color: var(--paper);
  border: 2px solid var(--border);
  border-radius: 6px;
  width: 480px;
  max-width: 100%;
  overflow: hidden;
  margin: 0 auto;
}

.ticket-header {
  background-color: var(--ink-dark);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
}

.studio-label {
  color: var(--cream);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 3px;
}

.order-badge {
  background-color: var(--rust);
  color: var(--cream);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  padding: 3px 10px;
  border-radius: 3px;
}

.ticket-body {
  display: flex;
  flex-direction: row;
  gap: 0;
}

.job-info {
  flex: 1 1 0;
  padding: 14px 16px;
  border-right: 1.5px dashed var(--border);
}

.job-title {
  font-size: 19px;
  font-weight: 700;
  color: var(--ink-dark);
  margin: 0 0 4px 0;
  line-height: 1.2;
}

.client-name {
  font-size: 12px;
  color: var(--muted);
  margin: 0 0 12px 0;
}

.spec-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.spec-item {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 12px;
  border-bottom: 1px dotted var(--border);
  padding-bottom: 5px;
}

.spec-key {
  color: var(--muted);
  font-weight: 500;
}

.spec-val {
  color: var(--ink-dark);
  font-weight: 600;
}

.job-side {
  flex: 0 0 160px;
  padding: 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.ink-swatches {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.swatch-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--muted);
  text-transform: uppercase;
}

.swatches {
  display: flex;
  flex-direction: row;
  gap: 8px;
}

.swatch {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 2px solid var(--border);
}

.swatch-a {
  background-color: var(--dusty-rose);
}

.swatch-b {
  background-color: var(--slate-blue);
}

.press-info {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.press-row {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.press-key {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--muted);
  text-transform: uppercase;
}

.press-val {
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-dark);
}

.press-val.due {
  color: var(--rust);
}

.status-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  background-color: var(--green-status-bg);
  border-radius: 4px;
  padding: 5px 10px;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--green-status);
  flex-shrink: 0;
}

.status-text {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--green-status);
}

.ticket-footer {
  background-color: var(--cream);
  border-top: 1.5px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 16px;
}

.footer-note {
  font-size: 10px;
  color: var(--muted);
  font-style: italic;
}

.footer-ref {
  font-size: 10px;
  font-weight: 700;
  color: var(--gold);
  letter-spacing: 1px;
}
